// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(c) && actor != address(0));
        amount = bound(amount, 1, 10 ether);

        // actor deposits `amount` via the fallback
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool depOk, ) = address(c).call{value: amount}("");
        assertTrue(depOk);
        assertTrue(address(c).balance == amount);

        // actor withdraws (locked re-entrancy-free payout)
        vm.prank(actor);
        try c.withdraw() {
            // General invariant: for every key k, the recorded balance must be
            // backed by contract Ether. Reference zeroes the paid balance, so
            // balances(actor)=0 <= contract balance always. Mutant leaves the
            // old balance while the Ether has left, so balances(actor)=amount
            // > 0 = contract balance breaks it.
            assertTrue(c.balances(actor) <= address(c).balance);
        } catch {
            // if the withdraw reverted, the balance must still be backed
            assertTrue(c.balances(actor) <= address(c).balance);
        }
    }
}
